import { createUserMessage } from '@deepseek-ai/dsh-llm'
import type { Context } from '@deepseek-ai/cordis'
import { TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol'
import type { ImageAttachmentRef } from '@deepseek-ai/dsh-attachment'
import type { LlmModelInfo, LlmResolvedModelInfo, StreamChunk } from '@deepseek-ai/dsh-llm'
import { DEFAULT_SETTINGS, MAX_OCR_CHARACTERS, MAX_OPTIMIZED_CHARACTERS, MAX_OPTIMIZE_CHARACTERS, MAX_POLISHED_CHARACTERS, MAX_TRANSCRIPT_CHARACTERS, OPTIMIZE_TIMEOUT_MS, POLISH_TIMEOUT_MS, validateSettings, type BetterInputSettings, type BetterInputSettingsPatch, type BetterInputSettingsView, type PolishRoute, type ReasoningEffortInfo } from '../config.js'
import { SettingsStore, type SettingsSnapshot } from '../settings-store.js'
import { optimizeUserText, polishUserText, resolveOptimizeSystemPrompt, resolvePolishSystemPrompt, OCR_SYSTEM_PROMPT, ocrUserText, OPTIMIZE_SYSTEM_PROMPT, POLISH_SYSTEM_PROMPT } from './prompts.js'
import { convertFile } from '../converter/to-markdown.js'
import { detectFormat } from '../converter/detect.js'
import { extractPptxImages, renderPdfPages, type OcrImage } from '../converter/ocr.js'
import type { ConvertibleFormat, ConvertResult } from '../converter/types.js'
import { MAX_INPUT_BYTES } from '../converter/types.js'
import type { TemplateInputWire, TemplateWire } from '../remote-contract.js'
import { TemplateStore } from '../templates/store.js'

/** Host-side settings file shape (flat for hand editing). */
type StoredSettings = BetterInputSettings

export class BetterInputPolishService extends TypertRemoteService {
  static inject = ['llm', 'attachments']
  private readonly settingsStore = new SettingsStore()
  private readonly templateStore = new TemplateStore()

  constructor(ctx: Context) {
    super(ctx, 'BetterInputPolish', { namespace: 'betterInput' })
  }

  /**
   * Read the current plugin settings from the plugin-owned document at
   * `~/.dsh/better-input/settings.json`. A genuinely unreadable document
   * degrades to `available: false` instead of failing the remote call.
   */
  async getSettings(): Promise<BetterInputSettingsView> {
    let snapshot: SettingsSnapshot
    try {
      snapshot = await this.settingsStore.read()
    } catch (error) {
      console.warn('[dsh-better-input] settings could not be read; reporting them as unavailable', error)
      return this.unavailableView()
    }
    return {
      available: true,
      writable: await this.settingsStore.isWritable(),
      settings: snapshot.settings,
      overridden: [...snapshot.overridden],
      defaultPolishPrompt: POLISH_SYSTEM_PROMPT,
      defaultOptimizePrompt: OPTIMIZE_SYSTEM_PROMPT
    }
  }

  async updateSettings(patch: BetterInputSettingsPatch, signal: AbortSignal): Promise<BetterInputSettingsView> {
    signal.throwIfAborted()
    let snapshot: SettingsSnapshot
    try {
      snapshot = await this.settingsStore.read()
    } catch (error) {
      // Nothing can be merged onto an unreadable document, and pretending the
      // write landed would be worse than reporting the store as unavailable.
      console.warn('[dsh-better-input] settings could not be read; refusing the write', error)
      return this.unavailableView()
    }
    const next: BetterInputSettings = { ...snapshot.settings }
    // Only the patch's own fields are persisted, so `overridden` keeps naming
    // exactly the keys the user set rather than every key in the document.
    const stored: Record<string, unknown> = {}
    for (const key of Object.keys(patch) as (keyof BetterInputSettings)[]) {
      const value = patch[key]
      if (value === undefined) continue
      Object.assign(next, { [key]: value })
      stored[key] = value
    }
    validateSettings(next)
    signal.throwIfAborted()
    await this.settingsStore.merge(stored)
    return this.getSettings()
  }

  /** Defaults-only view used when the settings document cannot be read. */
  private unavailableView(): BetterInputSettingsView {
    return {
      available: false,
      writable: false,
      settings: { ...DEFAULT_SETTINGS },
      overridden: [],
      defaultPolishPrompt: POLISH_SYSTEM_PROMPT,
      defaultOptimizePrompt: OPTIMIZE_SYSTEM_PROMPT
    }
  }

  /** Flattened settings for one Host operation; defaults when the store is unreadable. */
  private async currentSettings(): Promise<BetterInputSettings> {
    try {
      return (await this.settingsStore.read()).settings
    } catch {
      return { ...DEFAULT_SETTINGS }
    }
  }

  async listRoutes(): Promise<PolishRoute[]> {
    const routes: PolishRoute[] = []
    // NOTE: listRoutes intentionally skips per-model resolveModelInfo() calls.
    // Each resolution can require a roundtrip to the adapter/provider and a
    // registry with many models would make the settings page block for many
    // seconds on first open. Reasoning-effort metadata therefore arrives as
    // an empty array / undefined defaultEffort in the returned routes. The
    // settings UI hides the reasoning-effort dropdown entirely when the
    // list of efforts is empty, so users never see a half-populated menu.
    // We may add a dedicated resolveEfforts(provider, model) RPC in the
    // future if per-model lazy fetching becomes desirable.
    for (const provider of this.ctx.llm.listProviders()) {
      let models: readonly LlmModelInfo[]
      try {
        models = await this.ctx.llm.listModels(provider.id)
      } catch {
        continue
      }
      for (const model of models) {
        // NOTE: never assign an explicit `undefined` value. The Typert
        // gateway's boundary validation rejects any own-key holding
        // undefined as "not JSON-safe" after the Zod check passes, so
        // optional fields must simply be omitted.
        routes.push({
          provider: provider.id,
          providerName: provider.name,
          model: model.id,
          modelName: model.name,
          reasoningEfforts: []
        })
      }
    }
    return routes
  }

  /**
   * Lazily resolve reasoning efforts for a single route. Only called once the
   * settings UI actually displays that model's effort selector — so we never
   * blast the adapter/provide with hundreds of upfront resolveModelInfo calls.
   * Returns `{ efforts: [] }` (no defaultEffort key) if the metadata is
   * unavailable (adapter offline, model unknown, etc.).
   */
  async resolveModelEfforts(provider: string, model: string): Promise<{ efforts: readonly ReasoningEffortInfo[]; defaultEffort?: string }> {
    const resolved: LlmResolvedModelInfo | undefined = await (async () => {
      try {
        return await this.ctx.llm.resolveModelInfo(provider, model)
      } catch {
        return undefined
      }
    })()
    const reasoning = resolved?.reasoning
    const defaultEffort = reasoning?.defaultEffort != null ? String(reasoning.defaultEffort) : undefined
    // Optional fields are omitted rather than assigned undefined — the
    // gateway's JSON-safe boundary check rejects explicit undefined values.
    return {
      efforts: reasoning?.efforts?.map((effort) => ({
        id: String(effort.id),
        name: effort.name,
        ...(effort.description === undefined ? {} : { description: effort.description })
      })) ?? [],
      ...(defaultEffort === undefined ? {} : { defaultEffort })
    }
  }

  async polish(transcript: string, provider: string, model: string, signal: AbortSignal): Promise<string> {
    const raw = transcript.trim()
    if (raw === '' || raw.length > MAX_TRANSCRIPT_CHARACTERS || signal.aborted) return raw
    const settings = await this.currentSettings()
    const storedPrompt = settings.polishPrompt
    const effort = settings.polishReasoningEffort

    const routeProvider = provider.trim()
    const routeModel = model.trim()
    if (routeProvider === '' || routeModel === '') return raw

    const timeout = new AbortController()
    const timer = setTimeout(() => timeout.abort(), POLISH_TIMEOUT_MS)
    const forwardAbort = () => timeout.abort(signal.reason)
    signal.addEventListener('abort', forwardAbort, { once: true })

    try {
      const first = await this.completePolish(routeProvider, routeModel, raw, storedPrompt, effort, timeout.signal)
      if (first.trim() === raw && !timeout.signal.aborted && !signal.aborted) {
        // The model echoed the input unchanged; keep it rather than looping.
        return raw
      }
      return first
    } catch (error) {
      if (signal.aborted) return raw
      if (timeout.signal.aborted) throw new Error('The dsh LLM polishing request timed out')
      throw error instanceof Error ? error : new Error('The dsh LLM route did not complete polishing')
    } finally {
      clearTimeout(timer)
      signal.removeEventListener('abort', forwardAbort)
    }
  }

  async optimize(text: string, provider: string, model: string, context: string, signal: AbortSignal): Promise<string> {
    const raw = text.trim()
    if (raw === '' || raw.length > MAX_OPTIMIZE_CHARACTERS || signal.aborted) return raw
    const settings = await this.currentSettings()
    const storedPrompt = settings.optimizePrompt
    const effort = settings.optimizeReasoningEffort

    const routeProvider = provider.trim()
    const routeModel = model.trim()
    if (routeProvider === '' || routeModel === '') throw new Error('No dsh LLM route configured for prompt optimization')

    const timeout = new AbortController()
    const timer = setTimeout(() => timeout.abort(), OPTIMIZE_TIMEOUT_MS)
    const forwardAbort = () => timeout.abort(signal.reason)
    signal.addEventListener('abort', forwardAbort, { once: true })

    try {
      const result = await this.completeOptimize(routeProvider, routeModel, raw, context, storedPrompt, effort, timeout.signal)
      if (result.trim() === '' && !timeout.signal.aborted && !signal.aborted) {
        return raw
      }
      return result
    } catch (error) {
      if (signal.aborted) throw error
      if (timeout.signal.aborted) throw new Error('The dsh LLM optimize request timed out')
      throw error instanceof Error ? error : new Error('The dsh LLM route did not complete optimization')
    } finally {
      clearTimeout(timer)
      signal.removeEventListener('abort', forwardAbort)
    }
  }

  private async completePolish(provider: string, model: string, raw: string, storedPrompt: string, effort: string, signal: AbortSignal): Promise<string> {
    const config = await this.resolveEffortConfig(provider, model, effort, signal)
    const prepared = await this.ctx.llm.prepareCall(config, signal)
    const message = createUserMessage({
      content: [{ type: 'text', text: polishUserText(raw) }],
      source: { kind: 'user' }
    })
    const output = await collectText(prepared.stream({
      ...prepared.config,
      messages: [message],
      system: resolvePolishSystemPrompt(storedPrompt),
      signal
    }), MAX_POLISHED_CHARACTERS, 'polishing')
    if (output === '') throw new Error('The dsh LLM route returned no polished text')
    return output
  }

  private async completeOptimize(provider: string, model: string, raw: string, context: string, storedPrompt: string, effort: string, signal: AbortSignal): Promise<string> {
    const config = await this.resolveEffortConfig(provider, model, effort, signal)
    const prepared = await this.ctx.llm.prepareCall(config, signal)
    const message = createUserMessage({
      content: [{ type: 'text', text: optimizeUserText(raw) }],
      source: { kind: 'user' }
    })
    const output = await collectText(prepared.stream({
      ...prepared.config,
      messages: [message],
      system: resolveOptimizeSystemPrompt(storedPrompt, context),
      signal
    }), MAX_OPTIMIZED_CHARACTERS, 'optimization')
    if (output === '') throw new Error('The dsh LLM route returned no optimized text')
    return output
  }

  /**
   * Convert a binary file to Markdown on the Host. The raw bytes arrive as a
   * base64 string; we decode once and hand them to the converter package.
   * This runs only on the Host so the heavy parsing libraries never ship to
   * the browser.
   *
   * When `ocr` is true and the detected format is a raster-friendly document
   * (PDF pages / PPTX embedded images), conversion routes through the vision
   * model instead of the text-layer converters — for scanned or image-heavy
   * files whose text layer is empty. Any other file with `ocr` set falls back
   * to the normal text-layer conversion.
   */
  async convertFile(
    fileName: string,
    fileData: string,
    ocr: boolean | undefined,
    signal: AbortSignal
  ): Promise<{ success: boolean; format: ConvertibleFormat; markdown: string; warnings: readonly string[]; metadata?: { pageCount?: number; slideCount?: number; sheetCount?: number; wordCount?: number; fileCount?: number } }> {
    signal.throwIfAborted()
    const data = decodeBase64(fileData)
    if (data.length === 0) {
      throw new Error('文件内容为空')
    }
    // Independently guard the raw input size so an unexpectedly huge decoded
    // payload (e.g. an image-heavy PDF that is large on disk but yields little
    // text) cannot stall parsing — without conflating bytes with characters.
    if (data.byteLength > MAX_INPUT_BYTES) {
      throw new Error('文件过大，无法转换')
    }
    if (ocr) {
      const format = detectFormat(fileName, data)
      if (format === 'pdf' || format === 'pptx') {
        return this.ocrConvert(format, data, signal)
      }
    }
    return convertFile(fileName, data)
  }

  /** List all saved prompt templates (newest first). */
  async templatesList(): Promise<{ templates: TemplateWire[] }> {
    const templates = await this.templateStore.list()
    return { templates: templates.map((template) => ({ ...template, tags: [...template.tags] })) }
  }

  /**
   * Create or update one prompt template. Storage lives at
   * `~/.dsh/better-input/templates.json` on the Host machine — it survives
   * plugin updates, unlike anything stored inside the package directory.
   */
  async templatesSave(template: TemplateInputWire, signal: AbortSignal): Promise<{ template: TemplateWire }> {
    signal.throwIfAborted()
    const saved = await this.templateStore.save(template)
    return { template: { ...saved, tags: [...saved.tags] } }
  }

  /** Remove one prompt template by id. Missing ids resolve to `removed: false`. */
  async templatesRemove(id: string, signal: AbortSignal): Promise<{ removed: boolean }> {
    signal.throwIfAborted()
    const removed = await this.templateStore.remove(id)
    return { removed }
  }

  /**
   * OCR one scanned document through the configured vision model. Every page
   * (PDF) or embedded image (PPTX) is saved through the attachment store and
   * read by the model sequentially (one image per call), then concatenated
   * into a single Markdown document. A per-image failure is recorded as a
   * comment rather than aborting the whole conversion.
   */
  private async ocrConvert(
    format: 'pdf' | 'pptx',
    data: Uint8Array,
    signal: AbortSignal
  ): Promise<{ success: boolean; format: ConvertibleFormat; markdown: string; warnings: readonly string[]; metadata?: { pageCount?: number; slideCount?: number; sheetCount?: number; wordCount?: number; fileCount?: number } }> {
    const settings = await this.currentSettings()
    // OCR uses its own dedicated vision route — it deliberately does NOT fall
    // back to the polish model, so a scanned file can only be OCR-ready once
    // the user explicitly picked a vision model in Settings.
    const provider = settings.ocrProvider.trim()
    const model = settings.ocrModel.trim()
    if (provider === '' || model === '') {
      return { success: false, format, markdown: '', warnings: ['未配置 OCR 视觉模型，请在设置页选择'] }
    }
    if (this.ctx.attachments === undefined) {
      return { success: false, format, markdown: '', warnings: ['附件服务不可用，无法执行 OCR'] }
    }

    // Modality guard: only block when the route *explicitly* declares it does
    // NOT accept image input. A provider that omits the modality list is
    // "unknown", so we conservatively let it through — the adapter may still
    // upload images even if it does not advertise vision.
    try {
      const info = await this.ctx.llm.resolveModelInfo(provider, model, signal)
      const modalities = info.inputModalities
      if (modalities !== undefined && !modalities.includes('image')) {
        return { success: false, format, markdown: '', warnings: ['所选 OCR 模型不支持图片输入，请更换支持视觉的模型'] }
      }
    } catch {
      // Unknown modality — do not reject on a lookup failure.
    }

    let images: OcrImage[]
    try {
      images = format === 'pdf' ? await renderPdfPages(data) : await extractPptxImages(data)
    } catch (error) {
      return { success: false, format, markdown: '', warnings: [error instanceof Error ? error.message : 'OCR 图像解析失败'] }
    }
    signal.throwIfAborted()
    if (images.length === 0) {
      return { success: false, format, markdown: '', warnings: ['未从文件中提取到可识别的图片'] }
    }

    const parts: string[] = []
    for (const image of images) {
      signal.throwIfAborted()
      let text: string
      try {
        const ref = await this.ctx.attachments.saveImage({ data: image.data, mediaType: image.mediaType, name: image.name })
        text = await this.ocrOne(provider, model, ref, image.name, signal)
      } catch (error) {
        if (signal.aborted) throw error
        parts.push(`<!-- ${image.name}：OCR 中断（${error instanceof Error ? error.message : '未知错误'}） -->\n`)
        continue
      }
      if (text !== '') parts.push(`## ${image.name}\n\n${text}\n`)
    }

    const markdown = parts.join('\n').trim()
    if (markdown === '') {
      return { success: false, format, markdown: '', warnings: ['OCR 未能提取到有效内容'] }
    }
    return {
      success: true,
      format,
      markdown,
      warnings: [],
      metadata: format === 'pdf' ? { pageCount: images.length } : { slideCount: images.length },
    }
  }

  /** Run one vision-model read of a single saved image, returning its Markdown. */
  private async ocrOne(provider: string, model: string, ref: ImageAttachmentRef, imageName: string, signal: AbortSignal): Promise<string> {
    const prepared = await this.ctx.llm.prepareCall({ provider, model }, signal)
    const message = createUserMessage({
      content: [
        { type: 'image', attachment: ref },
        { type: 'text', text: ocrUserText(imageName) },
      ],
      source: { kind: 'user' },
    })
    return collectText(prepared.stream({
      ...prepared.config,
      messages: [message],
      system: OCR_SYSTEM_PROMPT,
      signal,
    }), MAX_OCR_CHARACTERS, 'OCR')
  }

  /**
   * Resolve the effective reasoning-effort wire config for one route. An
   * explicit stored selection is forwarded as-is. The empty default means
   * "thinking off": when the model advertises an `off` tier we send it, and
   * otherwise we omit the field so the adapter's own default applies.
   */
  private async resolveEffortConfig(provider: string, model: string, storedEffort: string, signal: AbortSignal): Promise<{ provider: string; model: string; reasoningEffort?: never }> {
    const selected = storedEffort.trim()
    if (selected !== '') return { provider, model, reasoningEffort: selected as never }
    try {
      const resolved = await this.ctx.llm.resolveModelInfo(provider, model, signal)
      const efforts = resolved.reasoning?.efforts ?? []
      const hasOff = efforts.some((effort) => String(effort.id) === 'off')
      return hasOff ? { provider, model, reasoningEffort: 'off' as never } : { provider, model }
    } catch {
      return { provider, model }
    }
  }
}

/** Decode a base64 string into bytes, tolerating a missing padding. */
function decodeBase64(input: string): Uint8Array {
  const clean = input.replace(/\s+/g, '')
  const padded = clean + '='.repeat((4 - (clean.length % 4)) % 4)
  const binary = atob(padded)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i)
  }
  return bytes
}

async function collectText(stream: AsyncIterable<StreamChunk>, maxCharacters: number, label: string): Promise<string> {
  let text = ''
  let sawDelta = false

  for await (const chunk of stream) {
    if (chunk.type === 'text-delta') {
      text += chunk.text
      if (text.length > maxCharacters) throw new Error(`The dsh LLM ${label} response is too large`)
      sawDelta = true
      continue
    }

    if (chunk.type === 'finish' && (chunk.reason.kind === 'error' || chunk.reason.kind === 'aborted')) {
      throw new Error(`The dsh LLM route did not complete ${label}`)
    }

    if (!sawDelta && chunk.type === 'block-end' && chunk.block.type === 'text') {
      text += chunk.block.text
      if (text.length > maxCharacters) throw new Error(`The dsh LLM ${label} response is too large`)
    }
  }

  return text.trim()
}
